/* -------------------------------------------------------------------------
 * FFmpeg binary management
 * ---------------------------------------------------------------------- */

/**
 * Return the path to the plugin-managed FFmpeg binary directory.
 * Stored inside wp-content/uploads so it survives plugin updates
 * and is writable without elevated permissions.
 */
function product_reels_bin_dir(): string {
	$upload = wp_upload_dir();
	return trailingslashit( $upload['basedir'] ) . 'product-reels-bin';
}

/**
 * Return the expected path of the plugin-managed binary for the current OS/arch.
 */
function product_reels_managed_binary(): string {
	$dir  = product_reels_bin_dir();
	$name = 'ffmpeg';
	if ( PHP_OS_FAMILY === 'Windows' ) {
		$name = 'ffmpeg.exe';
	}
	return $dir . DIRECTORY_SEPARATOR . $name;
}

/**
 * Detect the download URL for a static FFmpeg build that matches this server.
 * Returns [ 'url' => string, 'label' => string ] or null if unsupported.
 */
function product_reels_ffmpeg_download_info(): ?array {
	if ( PHP_OS_FAMILY === 'Windows' ) {
		return null; // Windows VPS not supported.
	}

	$arch = php_uname( 'm' ); // e.g. x86_64, aarch64, armv7l

	$base = 'https://johnvansickle.com/ffmpeg/releases/';

	if ( str_contains( $arch, 'x86_64' ) || str_contains( $arch, 'amd64' ) ) {
		return [
			'url'   => $base . 'ffmpeg-release-amd64-static.tar.xz',
			'arch'  => 'amd64',
			'label' => 'Linux x86_64 (amd64)',
		];
	}
	if ( str_contains( $arch, 'aarch64' ) || str_contains( $arch, 'arm64' ) ) {
		return [
			'url'   => $base . 'ffmpeg-release-arm64-static.tar.xz',
			'arch'  => 'arm64',
			'label' => 'Linux ARM64 (aarch64)',
		];
	}
	if ( str_contains( $arch, 'armv7' ) || str_contains( $arch, 'armhf' ) ) {
		return [
			'url'   => $base . 'ffmpeg-release-armhf-static.tar.xz',
			'arch'  => 'armhf',
			'label' => 'Linux ARMv7 (armhf)',
		];
	}

	return null; // Unsupported architecture.
}

/**
 * Resolve the active FFmpeg binary path, checking (in order):
 *   1. Plugin-managed binary in uploads/product-reels-bin/
 *   2. Manually entered path in settings
 *   3. Common system locations
 *   4. `which ffmpeg`
 */
function product_reels_ffmpeg_path(): string {
	static $path = null;
	if ( $path !== null ) {
		return $path;
	}

	// 1. Plugin-managed binary.
	$managed = product_reels_managed_binary();
	if ( file_exists( $managed ) && is_executable( $managed ) ) {
		$path = $managed;
		return $path;
	}

	// 2. Admin-specified path.
	$stored = get_option( 'product_reels_ffmpeg_path', '' );
	if ( $stored && is_executable( $stored ) ) {
		$path = $stored;
		return $path;
	}

	// 3. Common system locations.
	$candidates = [ '/usr/bin/ffmpeg', '/usr/local/bin/ffmpeg', '/opt/homebrew/bin/ffmpeg' ];
	foreach ( $candidates as $c ) {
		if ( is_executable( $c ) ) {
			$path = $c;
			return $path;
		}
	}

	// 4. PATH lookup.
	if ( function_exists( 'exec' ) ) {
		$out = [];
		exec( 'which ffmpeg 2>/dev/null', $out );
		if ( ! empty( $out[0] ) && is_executable( trim( $out[0] ) ) ) {
			$path = trim( $out[0] );
			return $path;
		}
	}

	$path = '';
	return $path;
}

function product_reels_has_ffmpeg(): bool {
	return product_reels_ffmpeg_path() !== '';
}

/**
 * Return a human-readable source label for the currently active binary.
 */
function product_reels_ffmpeg_source(): string {
	$active = product_reels_ffmpeg_path();
	if ( ! $active ) return 'none';
	if ( $active === product_reels_managed_binary() ) return 'managed';
	if ( $active === get_option( 'product_reels_ffmpeg_path', '' ) ) return 'manual';
	return 'system';
}

/* -------------------------------------------------------------------------
 * Main plugin class
 * ---------------------------------------------------------------------- */
class Product_Reels_Plugin {

	public function __construct() {
		add_action( 'plugins_loaded',              [ $this, 'load_textdomain' ] );
		add_action( 'init',                        [ $this, 'register_post_type' ] );
		add_action( 'add_meta_boxes',              [ $this, 'add_meta_boxes' ] );
		add_action( 'save_post_product_reel',      [ $this, 'save_reel' ] );
		add_action( 'wp_enqueue_scripts',          [ $this, 'enqueue_frontend_assets' ] );
		add_action( 'admin_enqueue_scripts',       [ $this, 'enqueue_admin_assets' ] );
		add_action( 'admin_notices',               [ $this, 'ffmpeg_admin_notice' ] );
		add_action( 'admin_menu',                  [ $this, 'add_settings_page' ] );
		add_action( 'admin_init',                  [ $this, 'register_settings' ] );
		add_action( 'wp_ajax_product_reels_generate_assets',     [ $this, 'ajax_generate_assets' ] );
		add_action( 'wp_ajax_product_reels_download_ffmpeg',      [ $this, 'ajax_download_ffmpeg' ] );
		add_action( 'wp_ajax_product_reels_download_ffmpeg_do',   [ $this, 'ajax_download_ffmpeg_do' ] );
		add_action( 'wp_ajax_product_reels_remove_ffmpeg',        [ $this, 'ajax_remove_ffmpeg' ] );
	}


	/* -----------------------------------------------------------------------
	 * Internationalization
	 * -------------------------------------------------------------------- */
	public function load_textdomain(): void {
		load_plugin_textdomain(
			'product-reels',
			false,
			dirname( plugin_basename( __FILE__ ) ) . '/languages'
		);
	}

	/* -----------------------------------------------------------------------
	 * Post type
	 * -------------------------------------------------------------------- */
	public function register_post_type(): void {
		register_post_type( 'product_reel', [
			'labels' => [
				'name'               => __( 'Product Reels', 'product-reels' ),
				'singular_name'      => __( 'Product Reel', 'product-reels' ),
				'add_new'            => __( 'Add New Reel', 'product-reels' ),
				'add_new_item'       => __( 'Add New Product Reel', 'product-reels' ),
				'edit_item'          => __( 'Edit Product Reel', 'product-reels' ),
				'new_item'           => __( 'New Product Reel', 'product-reels' ),
				'view_item'          => __( 'View Product Reel', 'product-reels' ),
				'search_items'       => __( 'Search Reels', 'product-reels' ),
				'not_found'          => __( 'No reels found.', 'product-reels' ),
				'not_found_in_trash' => __( 'No reels found in trash.', 'product-reels' ),
				'menu_name'          => __( 'Product Reels', 'product-reels' ),
			],
			'public'       => false,
			'show_ui'      => true,
			'menu_icon'    => 'dashicons-video-alt3',
			'supports'     => [ 'title', 'page-attributes' ],
			'show_in_rest' => true,
		] );
	}

