	/* -----------------------------------------------------------------------
	 * Save reel meta
	 * -------------------------------------------------------------------- */
	public function save_reel( int $post_id ): void {
		if ( ! isset( $_POST['product_reels_nonce'] ) ||
			! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['product_reels_nonce'] ) ), 'product_reels_save' ) ) {
			return;
		}
		if ( defined( 'DOING_AUTOSAVE' ) && DOING_AUTOSAVE ) {
			return;
		}
		if ( ! current_user_can( 'edit_post', $post_id ) ) {
			return;
		}

		$fields = [
			'_pr_video_source'          => 'sanitize_text_field',
			'_pr_video_url'             => 'esc_url_raw',
			'_pr_video_attachment_id'   => 'absint',
			'_pr_product_id'            => 'absint',
			'_pr_thumbnail_id'          => 'absint',
			'_pr_thumb_offset'          => 'absint',
			'_pr_preview_attachment_id' => 'absint',
			'_pr_preview_duration'      => 'absint',
		];

		foreach ( $fields as $key => $sanitizer ) {
			if ( isset( $_POST[ $key ] ) ) {
				$raw   = wp_unslash( $_POST[ $key ] );
				$value = $sanitizer( $raw );
				update_post_meta( $post_id, $key, $value );
			}
		}

		// Checkbox: preview enabled.
		$preview_enabled = isset( $_POST['_pr_preview_enabled'] ) ? '1' : '0';
		update_post_meta( $post_id, '_pr_preview_enabled', $preview_enabled );
	}

	/* -----------------------------------------------------------------------
	 * AJAX: Generate thumbnail or preview clip via FFmpeg
	 * -------------------------------------------------------------------- */
	public function ajax_generate_assets(): void {
		check_ajax_referer( 'product_reels_admin', 'nonce' );

		if ( ! current_user_can( 'edit_posts' ) ) {
			wp_send_json_error( [ 'message' => __( 'Permission denied.', 'product-reels' ) ] );
		}

		$post_id = absint( $_POST['post_id'] ?? 0 );
		$action  = sanitize_key( $_POST['generate'] ?? '' );

		if ( ! $post_id || ! in_array( $action, [ 'thumbnail', 'preview' ], true ) ) {
			wp_send_json_error( [ 'message' => __( 'Invalid request.', 'product-reels' ) ] );
		}

		if ( ! product_reels_has_ffmpeg() ) {
			wp_send_json_error( [ 'message' => __( 'FFmpeg is not available on this server.', 'product-reels' ) ] );
		}

		// Resolve video file path.
		$source = get_post_meta( $post_id, '_pr_video_source', true );
		if ( $source === 'upload' ) {
			$att_id    = absint( get_post_meta( $post_id, '_pr_video_attachment_id', true ) );
			$video_path = $att_id ? get_attached_file( $att_id ) : '';
		} else {
			$video_url  = get_post_meta( $post_id, '_pr_video_url', true );
			$video_path = $video_url ? $this->fetch_remote_video( $video_url ) : '';
		}

		if ( ! $video_path || ! file_exists( $video_path ) ) {
			wp_send_json_error( [ 'message' => __( 'Video file not found. Please save the reel first.', 'product-reels' ) ] );
		}

		$upload_dir = wp_upload_dir();
		$dest_dir   = trailingslashit( $upload_dir['path'] );
		$ffmpeg     = product_reels_ffmpeg_path();
		$slug       = 'pr-' . $post_id . '-' . time();

		if ( $action === 'thumbnail' ) {
			$offset   = absint( get_post_meta( $post_id, '_pr_thumb_offset', true ) );
			$out_file = $dest_dir . $slug . '-thumb.jpg';
			$cmd      = sprintf(
				'%s -y -ss %d -i %s -frames:v 1 -q:v 2 %s 2>&1',
				escapeshellarg( $ffmpeg ),
				$offset,
				escapeshellarg( $video_path ),
				escapeshellarg( $out_file )
			);
			shell_exec( $cmd );
			if ( ! file_exists( $out_file ) ) {
				wp_send_json_error( [ 'message' => __( 'FFmpeg failed to generate the thumbnail.', 'product-reels' ) ] );
			}
			$att_id = $this->sideload_file( $out_file, $post_id, 'jpg' );
			if ( is_wp_error( $att_id ) ) {
				wp_send_json_error( [ 'message' => $att_id->get_error_message() ] );
			}
			// Remove old thumbnail attachment if different.
			$old_id = absint( get_post_meta( $post_id, '_pr_thumbnail_id', true ) );
			if ( $old_id && $old_id !== $att_id ) {
				wp_delete_attachment( $old_id, true );
			}
			update_post_meta( $post_id, '_pr_thumbnail_id', $att_id );
			wp_send_json_success( [
				'attachment_id' => $att_id,
				'url'           => wp_get_attachment_url( $att_id ),
				'message'       => __( 'Thumbnail generated!', 'product-reels' ),
			] );
		}

		if ( $action === 'preview' ) {
			$duration = absint( get_post_meta( $post_id, '_pr_preview_duration', true ) ) ?: 5;
			$out_file = $dest_dir . $slug . '-preview.mp4';
			// Trim + strip audio + scale to max 480px wide + high quality compression.
			$cmd = sprintf(
				'%s -y -i %s -t %d -an -vf "scale=\'min(480,iw)\':-2" -c:v libx264 -preset fast -crf 28 -movflags +faststart %s 2>&1',
				escapeshellarg( $ffmpeg ),
				escapeshellarg( $video_path ),
				$duration,
				escapeshellarg( $out_file )
			);
			shell_exec( $cmd );
			if ( ! file_exists( $out_file ) ) {
				wp_send_json_error( [ 'message' => __( 'FFmpeg failed to generate the preview clip.', 'product-reels' ) ] );
			}
			$att_id = $this->sideload_file( $out_file, $post_id, 'mp4' );
			if ( is_wp_error( $att_id ) ) {
				wp_send_json_error( [ 'message' => $att_id->get_error_message() ] );
			}
			$old_id = absint( get_post_meta( $post_id, '_pr_preview_attachment_id', true ) );
			if ( $old_id && $old_id !== $att_id ) {
				wp_delete_attachment( $old_id, true );
			}
			update_post_meta( $post_id, '_pr_preview_attachment_id', $att_id );
			wp_send_json_success( [
				'attachment_id' => $att_id,
				'url'           => wp_get_attachment_url( $att_id ),
				'message'       => sprintf( __( 'Preview clip generated (%ds)!', 'product-reels' ), $duration ),
			] );
		}
	}

	/* -----------------------------------------------------------------------
	 * Helpers
	 * -------------------------------------------------------------------- */

	/**
	 * Download a remote video to a temp file and return the local path.
	 */
	private function fetch_remote_video( string $url ): string {
		$tmp = download_url( $url );
		if ( is_wp_error( $tmp ) ) {
			return '';
		}
		// Rename with extension so FFmpeg can detect the format.
		$ext  = pathinfo( parse_url( $url, PHP_URL_PATH ), PATHINFO_EXTENSION ) ?: 'mp4';
		$dest = $tmp . '.' . $ext;
		rename( $tmp, $dest );
		return $dest;
	}

	/**
	 * Register a local file as a Media Library attachment and delete the temp file.
	 *
	 * @return int|\WP_Error
	 */
	private function sideload_file( string $file, int $post_id, string $ext ) {
		require_once ABSPATH . 'wp-admin/includes/file.php';
		require_once ABSPATH . 'wp-admin/includes/media.php';
		require_once ABSPATH . 'wp-admin/includes/image.php';

		$upload_dir  = wp_upload_dir();
		$upload_path = trailingslashit( $upload_dir['path'] );
		$filename    = basename( $file );
		$new_path    = $upload_path . $filename;

		if ( $file !== $new_path ) {
			if ( ! copy( $file, $new_path ) ) {
				return new \WP_Error( 'copy_failed', __( 'Could not copy generated file to uploads directory.', 'product-reels' ) );
			}
			@unlink( $file );
		}

		$filetype = wp_check_filetype( $filename, null );
		$att_id   = wp_insert_attachment( [
			'guid'           => trailingslashit( $upload_dir['url'] ) . $filename,
			'post_mime_type' => $filetype['type'],
			'post_title'     => preg_replace( '/\.[^.]+$/', '', $filename ),
			'post_content'   => '',
			'post_status'    => 'inherit',
		], $new_path, $post_id );

		if ( is_wp_error( $att_id ) ) {
			return $att_id;
		}

		$metadata = wp_generate_attachment_metadata( $att_id, $new_path );
		wp_update_attachment_metadata( $att_id, $metadata );

		return $att_id;
	}

