	public function ffmpeg_admin_notice(): void {
		$screen = get_current_screen();
		if ( ! $screen || $screen->post_type !== 'product_reel' ) {
			return;
		}
		if ( ! product_reels_has_ffmpeg() ) {
			echo '<div class="notice notice-warning is-dismissible"><p>';
			printf(
				/* translators: %s: settings page link */
				esc_html__( '⚠️ Product Reels: FFmpeg was not detected on this server. Thumbnail and preview generation are disabled. %s', 'product-reels' ),
				'<a href="' . esc_url( admin_url( 'edit.php?post_type=product_reel&page=product-reels-settings' ) ) . '">' . esc_html__( 'Set a custom FFmpeg path →', 'product-reels' ) . '</a>'
			);
			echo '</p></div>';
		}
	}

