		</div><!-- /.wrap -->
		<?php
	}

	/* -----------------------------------------------------------------------
	 * AJAX: Download FFmpeg static binary
	 * -------------------------------------------------------------------- */
	public function ajax_download_ffmpeg(): void {
		check_ajax_referer( 'product_reels_admin', 'nonce' );

		if ( ! current_user_can( 'manage_options' ) ) {
			wp_send_json_error( [ 'message' => __( 'Permission denied.', 'product-reels' ) ] );
		}

		$download_info = product_reels_ffmpeg_download_info();
		if ( ! $download_info ) {
			wp_send_json_error( [ 'message' => __( 'Automatic download is not supported for this server architecture.', 'product-reels' ) ] );
		}

		// Ensure bin directory exists.
		$bin_dir = product_reels_bin_dir();
		if ( ! is_dir( $bin_dir ) ) {
			wp_mkdir_p( $bin_dir );
			file_put_contents( $bin_dir . '/.htaccess', "Order deny,allow\nDeny from all\n" );
		}

		if ( ! is_writable( $bin_dir ) ) {
			wp_send_json_error( [ 'message' => sprintf(
				/* translators: %s: directory path */
				__( 'Directory is not writable: %s', 'product-reels' ),
				$bin_dir
			) ] );
		}

		// This is a blocking call — JS should display a spinner before triggering it.
		$this->ajax_download_ffmpeg_do();
	}

	/**
	 * Second phase: blocking download + extraction.
	 * JS calls this after the first ack so the UI can show a spinner.
	 */
	public function ajax_download_ffmpeg_do(): void {
		check_ajax_referer( 'product_reels_admin', 'nonce' );

		if ( ! current_user_can( 'manage_options' ) ) {
			wp_send_json_error( [ 'message' => __( 'Permission denied.', 'product-reels' ) ] );
		}

		// Increase time limit — large file download can take a while.
		if ( function_exists( 'set_time_limit' ) ) {
			@set_time_limit( 300 );
		}

		$download_info = product_reels_ffmpeg_download_info();
		if ( ! $download_info ) {
			wp_send_json_error( [ 'message' => __( 'Unsupported architecture.', 'product-reels' ) ] );
		}

		$bin_dir = product_reels_bin_dir();
		if ( ! is_dir( $bin_dir ) ) {
			wp_mkdir_p( $bin_dir );
			file_put_contents( $bin_dir . '/.htaccess', "Order deny,allow\nDeny from all\n" );
		}

		$tarball = $bin_dir . '/ffmpeg-static.tar.xz';

		// Download via WP HTTP (handles SSL, proxies, etc.).
		$response = wp_remote_get( $download_info['url'], [
			'timeout'  => 300,
			'stream'   => true,
			'filename' => $tarball,
		] );

		if ( is_wp_error( $response ) ) {
			wp_send_json_error( [ 'message' => $response->get_error_message() ] );
		}

		$code = wp_remote_retrieve_response_code( $response );
		if ( $code !== 200 ) {
			wp_send_json_error( [ 'message' => sprintf( __( 'Download failed (HTTP %d).', 'product-reels' ), $code ) ] );
		}

		if ( ! file_exists( $tarball ) || filesize( $tarball ) < 1024 * 1024 ) {
			wp_send_json_error( [ 'message' => __( 'Downloaded file appears corrupt or too small.', 'product-reels' ) ] );
		}

		// Extract only the ffmpeg binary from the tarball.
		// The archive structure is: ffmpeg-*-static/ffmpeg
		$binary_dest = product_reels_managed_binary();
		$cmd = sprintf(
			'tar -xJf %s --wildcards --no-anchored "ffmpeg" -O > %s 2>&1',
			escapeshellarg( $tarball ),
			escapeshellarg( $binary_dest )
		);
		$output = [];
		$return_code = 0;
		exec( $cmd, $output, $return_code );

		// Clean up tarball regardless.
		@unlink( $tarball );

		if ( $return_code !== 0 || ! file_exists( $binary_dest ) || filesize( $binary_dest ) < 1024 * 100 ) {
			wp_send_json_error( [
				'message' => __( 'Extraction failed. The tar command may not support .xz on this server.', 'product-reels' )
					. ( $output ? ' ' . implode( ' ', $output ) : '' ),
			] );
		}

		// Make executable.
		chmod( $binary_dest, 0755 );

		// Verify it runs.
		$ver = [];
		exec( escapeshellarg( $binary_dest ) . ' -version 2>&1', $ver );
		$version_line = $ver[0] ?? '';

		// Store the path so detection picks it up immediately.
		// (The managed path check in product_reels_ffmpeg_path() handles this,
		//  but clearing the static cache ensures the settings page reflects it.)
		wp_send_json_success( [
			'message' => sprintf(
				/* translators: %s: ffmpeg version string */
				__( 'FFmpeg installed successfully! %s', 'product-reels' ),
				$version_line ? '(' . esc_html( $version_line ) . ')' : ''
			),
			'path'    => $binary_dest,
		] );
	}

	/* -----------------------------------------------------------------------
	 * AJAX: Remove managed FFmpeg binary
	 * -------------------------------------------------------------------- */
	public function ajax_remove_ffmpeg(): void {
		check_ajax_referer( 'product_reels_admin', 'nonce' );

		if ( ! current_user_can( 'manage_options' ) ) {
			wp_send_json_error( [ 'message' => __( 'Permission denied.', 'product-reels' ) ] );
		}

		$managed = product_reels_managed_binary();
		if ( file_exists( $managed ) ) {
			unlink( $managed );
		}
		// Also remove the htaccess we created.
		$htaccess = product_reels_bin_dir() . '/.htaccess';
		if ( file_exists( $htaccess ) ) {
			@unlink( $htaccess );
		}

		wp_send_json_success( [ 'message' => __( 'Managed FFmpeg binary removed.', 'product-reels' ) ] );
	}
}

/* =========================================================================
 * Front-end render function
 * ====================================================================== */
function product_reels_render_section(): void {
	$reels = new WP_Query( [
		'post_type'      => 'product_reel',
		'posts_per_page' => 20,
		'orderby'        => [ 'menu_order' => 'ASC', 'date' => 'DESC' ],
	] );

	if ( ! $reels->have_posts() ) {
		return;
	}
	?>
	<section class="reels-section" id="reels">
		<div class="reels-wrap">
			<button class="carousel-control carousel-control--prev reels-control--prev" type="button" aria-label="<?php esc_attr_e( 'Previous reels', 'product-reels' ); ?>">
				<span aria-hidden="true">‹</span>
			</button>
			<div class="reels-grid" tabindex="0" role="list">
				<?php while ( $reels->have_posts() ) :
					$reels->the_post();
					$post_id = get_the_ID();

					$source         = get_post_meta( $post_id, '_pr_video_source', true );
					$video_url      = '';
					if ( $source === 'upload' ) {
						$att_id    = absint( get_post_meta( $post_id, '_pr_video_attachment_id', true ) );
						$video_url = $att_id ? wp_get_attachment_url( $att_id ) : '';
					} else {
						$video_url = get_post_meta( $post_id, '_pr_video_url', true );
					}

					if ( ! $video_url ) {
						continue;
					}

					$thumb_id       = absint( get_post_meta( $post_id, '_pr_thumbnail_id', true ) );
					$thumb_url      = $thumb_id ? wp_get_attachment_url( $thumb_id ) : '';
					$preview_enabled = get_post_meta( $post_id, '_pr_preview_enabled', true );
					$preview_id     = absint( get_post_meta( $post_id, '_pr_preview_attachment_id', true ) );
					$preview_url    = ( $preview_enabled && $preview_id ) ? wp_get_attachment_url( $preview_id ) : '';

					$product_id     = absint( get_post_meta( $post_id, '_pr_product_id', true ) );
					$linked_product = $product_id && function_exists( 'wc_get_product' ) ? wc_get_product( $product_id ) : null;
					?>
					<article class="reel-card" role="listitem"
						data-full-src="<?php echo esc_url( $video_url ); ?>">
						<div class="reel-video" data-full-src="<?php echo esc_url( $video_url ); ?>">
							<?php if ( $preview_url ) : ?>
								<video class="reel-video__preview"
									data-full-src="<?php echo esc_url( $video_url ); ?>"
									src="<?php echo esc_url( $preview_url ); ?>"
									<?php if ( $thumb_url ) : ?>poster="<?php echo esc_url( $thumb_url ); ?>"<?php endif; ?>
									autoplay muted loop playsinline></video>
							<?php else : ?>
								<video class="reel-video__preview"
									data-full-src="<?php echo esc_url( $video_url ); ?>"
									<?php if ( $thumb_url ) : ?>poster="<?php echo esc_url( $thumb_url ); ?>"<?php endif; ?>
									muted loop playsinline></video>
							<?php endif; ?>
						</div>
						<?php if ( $linked_product ) : ?>
							<a href="<?php echo esc_url( get_permalink( $product_id ) ); ?>" class="reel-product">
								<?php echo $linked_product->get_image( 'thumbnail' ); ?>
								<div class="reel-product-info">
									<strong><?php echo esc_html( $linked_product->get_name() ); ?></strong>
									<span><?php echo wp_kses_post( $linked_product->get_price_html() ); ?></span>
								</div>
							</a>
						<?php endif; ?>
					</article>
				<?php endwhile; wp_reset_postdata(); ?>
			</div>
			<button class="carousel-control carousel-control--next reels-control--next" type="button" aria-label="<?php esc_attr_e( 'Next reels', 'product-reels' ); ?>">
				<span aria-hidden="true">›</span>
			</button>
		</div>
	</section>
	<?php
}

new Product_Reels_Plugin();